SELECT [Цена топлива индексированная].NAME, [Цена топлива индексированная].NUMB1120, [Цена топлива индексированная].Year, [Цена топлива индексированная].cena_gaza_ind, [Цена топлива индексированная].cena_ugol_ind, [Цена топлива индексированная].cena_e, [Цена топлива индексированная].cena_Be, Станции2021.EURT
FROM Станции2021 INNER JOIN [Цена топлива индексированная] ON Станции2021.NUMB1120 = [Цена топлива индексированная].NUMB1120;
